package com.paramichha.testkit;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import static com.paramichha.testkit.utils.FormatJavaFile.removeUnUsedImport;

/**
 * A single generated Java source file.
 */
public record JavaSourceCode(
        String packageName,
        String className,
        String source
) {
    public JavaSourceCode {
        source = removeUnUsedImport(source);
    }

    /** Text every generated file carries in its header. A file without it is hand-owned. */
    public static final String OWNERSHIP_MARKER = "Generated by TestKit";

    /**
     * True when {@code file} exists and does not carry {@link #OWNERSHIP_MARKER}: someone removed
     * the marker, or wrote the file by hand. Generation must leave such a file alone.
     */
    public static boolean isHandOwned(Path file) {
        if (!Files.exists(file)) return false;
        try {
            return !Files.readString(file).contains(OWNERSHIP_MARKER);
        } catch (IOException e) {
            return true;   // unreadable: do not overwrite what we cannot inspect
        }
    }

    /**
     * Writes the file unless it exists and is hand-owned (see {@link #isHandOwned}). Returns the
     * file's path either way; check {@link #isHandOwned} first to know whether it was skipped.
     */
    public Path writeTo(Path sourceRoot) {
        try {
            Path dir = sourceRoot;
            for (String part : packageName.split("\\.")) dir = dir.resolve(part);
            Files.createDirectories(dir);
            Path file = dir.resolve(className + ".java");
            if (isHandOwned(file)) return file;
            if (Files.exists(file) && Files.readString(file).equals(source))
                return file;
            Files.writeString(file, source);
            return file;
        } catch (IOException e) {
            throw new TestKitException("Failed to write " + className + ".java", e);
        }
    }

    public String asString() { return source; }
}